import Foundation
import DesignPilotSDK

/// Transpiles semantic AST elements into UIKit UIViewController / UIView source code.
public struct UIKitLayoutGenerator: Sendable {
    public init() {}

    public func generate(ast: ASTElement, screenName: String) -> String {
        let sanitizedName = sanitizeName(screenName)

        return """
        //
        //  \(sanitizedName)ViewController.swift
        //  Generated by DesignPilot SDK v1.0
        //  Native UIKit AutoLayout Architecture
        //

        import UIKit

        public class \(sanitizedName)ViewController: UIViewController {

            private let scrollView: UIScrollView = {
                let sv = UIScrollView()
                sv.translatesAutoresizingMaskIntoConstraints = false
                sv.showsVerticalScrollIndicator = false
                return sv
            }()

            private let contentStackView: UIStackView = {
                let stack = UIStackView()
                stack.translatesAutoresizingMaskIntoConstraints = false
                stack.axis = .vertical
                stack.spacing = 16
                stack.alignment = .fill
                stack.distribution = .fill
                return stack
            }()

            public override func viewDidLoad() {
                super.viewDidLoad()
                setupViews()
                setupConstraints()
            }

            private func setupViews() {
                view.backgroundColor = .systemBackground
                view.addSubview(scrollView)
                scrollView.addSubview(contentStackView)

                title = "\(sanitizedName)"
                navigationController?.navigationBar.prefersLargeTitles = true
            }

            private func setupConstraints() {
                NSLayoutConstraint.activate([
                    scrollView.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor),
                    scrollView.leadingAnchor.constraint(equalTo: view.leadingAnchor),
                    scrollView.trailingAnchor.constraint(equalTo: view.trailingAnchor),
                    scrollView.bottomAnchor.constraint(equalTo: view.bottomAnchor),

                    contentStackView.topAnchor.constraint(equalTo: scrollView.contentLayoutGuide.topAnchor, constant: 16),
                    contentStackView.leadingAnchor.constraint(equalTo: scrollView.contentLayoutGuide.leadingAnchor, constant: 16),
                    contentStackView.trailingAnchor.constraint(equalTo: scrollView.contentLayoutGuide.trailingAnchor, constant: -16),
                    contentStackView.bottomAnchor.constraint(equalTo: scrollView.contentLayoutGuide.bottomAnchor, constant: -16),
                    contentStackView.widthAnchor.constraint(equalTo: scrollView.frameLayoutGuide.widthAnchor, constant: -32)
                ])
            }
        }
        """
    }

    private func sanitizeName(_ name: String) -> String {
        let cleaned = name.components(separatedBy: CharacterSet.alphanumerics.inverted).joined()
        return cleaned.isEmpty ? "GeneratedScreen" : cleaned
    }
}
